public int rob(int[] nums) {              // House Robber I
    int prev = 0, cur = 0;                 // prev = best up to i-2, cur = up to i-1
    for (int x : nums) {
        int t = Math.max(cur, prev + x);
        prev = cur; cur = t;
    }
    return cur;
}
public int robII(int[] nums) {
    if (nums.length == 1) return nums[0];
    return Math.max(robRange(nums, 0, nums.length - 2),
                    robRange(nums, 1, nums.length - 1));
}
private int robRange(int[] nums, int lo, int hi) {
    int prev = 0, cur = 0;
    for (int i = lo; i <= hi; i++) {
        int t = Math.max(cur, prev + nums[i]);
        prev = cur; cur = t;
    }
    return cur;
}

public int numDecodings(String s) {
    int n = s.length();
    int prev2 = 1;                        // dp[0]
    int prev1 = s.charAt(0) == '0' ? 0 : 1; // dp[1]
    for (int i = 2; i <= n; i++) {
        int cur = 0;
        if (s.charAt(i - 1) != '0') cur += prev1;
        int two = (s.charAt(i - 2) - '0') * 10 + (s.charAt(i - 1) - '0');
        if (two >= 10 && two <= 26) cur += prev2;
        prev2 = prev1; prev1 = cur;
    }
    return prev1;
}

public boolean wordBreak(String s, java.util.List<String> wordDict) {
    java.util.Set<String> dict = new java.util.HashSet<>(wordDict);
    int n = s.length(), maxLen = 0;
    for (String w : dict) maxLen = Math.max(maxLen, w.length());
    boolean[] dp = new boolean[n + 1];
    dp[0] = true;
    for (int i = 1; i <= n; i++)
        for (int j = Math.max(0, i - maxLen); j < i; j++)
            if (dp[j] && dict.contains(s.substring(j, i))) { dp[i] = true; break; }
    return dp[n];
}

public int jump(int[] nums) {
    int jumps = 0, curEnd = 0, farthest = 0;
    for (int i = 0; i < nums.length - 1; i++) {
        farthest = Math.max(farthest, i + nums[i]);
        if (i == curEnd) { jumps++; curEnd = farthest; }
    }
    return jumps;
}

public int maxProduct(int[] nums) {
    int maxEnd = nums[0], minEnd = nums[0], best = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int x = nums[i];
        if (x < 0) { int t = maxEnd; maxEnd = minEnd; minEnd = t; }
        maxEnd = Math.max(x, x * maxEnd);
        minEnd = Math.min(x, x * minEnd);
        best = Math.max(best, maxEnd);
    }
    return best;
}

public int lengthOfLIS_dp(int[] nums) {
    int n = nums.length, best = 0;
    int[] dp = new int[n];
    for (int i = 0; i < n; i++) {
        dp[i] = 1;
        for (int j = 0; j < i; j++)
            if (nums[j] < nums[i]) dp[i] = Math.max(dp[i], dp[j] + 1);
        best = Math.max(best, dp[i]);
    }
    return best;
}

public int lengthOfLIS(int[] nums) {
    int[] tails = new int[nums.length];
    int size = 0;
    for (int x : nums) {
        int lo = 0, hi = size;
        while (lo < hi) {              // first index with tails[idx] >= x
            int mid = (lo + hi) >>> 1;
            if (tails[mid] < x) lo = mid + 1; else hi = mid;
        }
        tails[lo] = x;
        if (lo == size) size++;
    }
    return size;
}

public boolean canPartition(int[] nums) {
    int total = 0;
    for (int x : nums) total += x;
    if ((total & 1) == 1) return false;
    int target = total / 2;
    boolean[] dp = new boolean[target + 1];
    dp[0] = true;
    for (int x : nums)
        for (int s = target; s >= x; s--)
            dp[s] |= dp[s - x];
    return dp[target];
}

public int findTargetSumWays(int[] nums, int target) {
    int total = 0;
    for (int x : nums) total += x;
    if (Math.abs(target) > total || ((total + target) & 1) == 1) return 0;
    int P = (total + target) / 2;
    int[] dp = new int[P + 1];
    dp[0] = 1;
    for (int x : nums)
        for (int s = P; s >= x; s--)
            dp[s] += dp[s - x];
    return dp[P];
}

public int coinChange(int[] coins, int amount) {      // I: min coins
    int[] dp = new int[amount + 1];
    java.util.Arrays.fill(dp, amount + 1);
    dp[0] = 0;
    for (int c : coins)
        for (int a = c; a <= amount; a++)
            dp[a] = Math.min(dp[a], dp[a - c] + 1);
    return dp[amount] > amount ? -1 : dp[amount];
}
public int change(int amount, int[] coins) {          // II: count ways
    int[] dp = new int[amount + 1];
    dp[0] = 1;
    for (int c : coins)                                // coins outside => combinations
        for (int a = c; a <= amount; a++)
            dp[a] += dp[a - c];
    return dp[amount];
}

public int lastStoneWeightII(int[] stones) {
    int total = 0;
    for (int s : stones) total += s;
    int half = total / 2;
    boolean[] dp = new boolean[half + 1];
    dp[0] = true;
    int best = 0;
    for (int s : stones)
        for (int w = half; w >= s; w--)
            if (dp[w - s]) { dp[w] = true; best = Math.max(best, w); }
    return total - 2 * best;
}

public int findMaxForm(String[] strs, int m, int n) {
    int[][] dp = new int[m + 1][n + 1];
    for (String s : strs) {
        int z = 0, o = 0;
        for (char c : s.toCharArray()) { if (c == '0') z++; else o++; }
        for (int i = m; i >= z; i--)
            for (int j = n; j >= o; j--)
                dp[i][j] = Math.max(dp[i][j], dp[i - z][j - o] + 1);
    }
    return dp[m][n];
}

public int profitableSchemes(int n, int minProfit, int[] group, int[] profit) {
    int MOD = 1_000_000_007;
    long[][] dp = new long[n + 1][minProfit + 1];
    for (int g = 0; g <= n; g++) dp[g][0] = 1;      // 0 required profit: empty scheme counts
    for (int k = 0; k < group.length; k++) {
        int g = group[k], p = profit[k];
        for (int i = n; i >= g; i--)
            for (int j = minProfit; j >= 0; j--) {
                int pp = Math.min(minProfit, j + p);
                dp[i][pp] = (dp[i][pp] + dp[i - g][j]) % MOD;
            }
    }
    return (int) dp[n][minProfit];
}

public int numRollsToTarget(int n, int k, int target) {
    int MOD = 1_000_000_007;
    int[] dp = new int[target + 1];
    dp[0] = 1;
    for (int d = 1; d <= n; d++) {
        int[] next = new int[target + 1];
        for (int t = 1; t <= target; t++)
            for (int f = 1; f <= k && f <= t; f++)
                next[t] = (next[t] + dp[t - f]) % MOD;
        dp = next;
    }
    return dp[target];
}

public String largestNumber(int[] cost, int target) {
    int[] dp = new int[target + 1];
    java.util.Arrays.fill(dp, Integer.MIN_VALUE);
    dp[0] = 0;
    for (int t = 1; t <= target; t++)
        for (int d = 0; d < 9; d++)
            if (t >= cost[d] && dp[t - cost[d]] != Integer.MIN_VALUE)
                dp[t] = Math.max(dp[t], dp[t - cost[d]] + 1);
    if (dp[target] < 0) return "0";

    StringBuilder sb = new StringBuilder();
    int t = target;
    for (int d = 8; d >= 0; d--)                 // try larger digits first
        while (t >= cost[d] && dp[t] == dp[t - cost[d]] + 1) {
            sb.append((char) ('1' + d));
            t -= cost[d];
        }
    return sb.toString();
}
